diff --git a/tests/Test-RemoteMarker.Tests.ps1 b/tests/Test-RemoteMarker.Tests.ps1
index 3333333..4444444 100644
--- a/tests/Test-RemoteMarker.Tests.ps1
+++ b/tests/Test-RemoteMarker.Tests.ps1
@@ -1,3 +1,22 @@
 Describe 'Test-RemoteMarker' {
+    BeforeAll {
+        . "$PSScriptRoot/../src/Test-RemoteMarker.ps1"
+    }
+    It 'binds MarkerPath into the isolated remote script block' {
+        Mock Test-Path {
+            param($LiteralPath)
+            $LiteralPath -eq 'C:\IR\ready.flag'
+        }
+        Mock Invoke-Command {
+            param($ComputerName, $ScriptBlock, $ArgumentList)
+            $MarkerPath = $null
+            & $ScriptBlock @ArgumentList
+        }
+        Test-RemoteMarker -ComputerName host1 -MarkerPath 'C:\IR\ready.flag' | Should -BeTrue
+        Assert-MockCalled Invoke-Command -Times 1 -ParameterFilter {
+            $ComputerName -eq 'host1' -and $ArgumentList[0] -eq 'C:\IR\ready.flag'
+        }
+        Assert-MockCalled Test-Path -Times 1 -ParameterFilter {
+            $LiteralPath -eq 'C:\IR\ready.flag'
+        }
+    }
 }
